<script setup>
import { onMounted, ref } from 'vue'
import { api } from '../services/api'
const overview = ref(null)
const updating = ref(null)
onMounted(async () => { overview.value = await api.getAdminOverview() })
async function updateStatus(reportId, status) { updating.value = reportId; overview.value = await api.updateReportStatus(reportId, status); updating.value = null }
</script>

<template>
  <section class="page-shell"><div class="container"><div class="d-flex justify-content-between align-items-end gap-3 mb-4"><div><p class="eyebrow">Administrator workspace</p><h1 class="page-title">Content overview.</h1><p class="page-subtitle">Review activity and keep the UniMeal community useful and safe.</p></div><span class="soft-badge">Mock admin data</span></div><div v-if="!overview" class="py-5 text-center text-secondary">Loading administration data...</div><template v-else><div class="row g-4"><div v-for="card in overview.statistics" :key="card.label" class="col-sm-6 col-xl-3"><article class="surface-card p-4 h-100"><p class="stat-label">{{ card.label }}</p><strong class="stat-value">{{ card.value }}</strong><p class="stat-note mb-0">{{ card.note }}</p></article></div></div><section class="surface-card p-4 p-md-5 mt-4"><div class="d-flex flex-column flex-md-row justify-content-between gap-2 mb-3"><div><h2 class="admin-heading">Reported content</h2><p class="text-secondary mb-0">Reports must target either one recipe or one comment.</p></div><span class="text-secondary small">{{ overview.reports.length }} reports</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Target</th><th>Reporter</th><th>Reason</th><th>Status</th><th class="text-end">Review</th></tr></thead><tbody><tr v-for="report in overview.reports" :key="report.id"><td><strong>{{ report.targetTitle }}</strong><small>{{ report.targetType }} · {{ report.createdAt }}</small></td><td>{{ report.reporter }}</td><td>{{ report.reason }}</td><td><span class="status-pill" :class="report.status.toLowerCase().replace(' ', '-')">{{ report.status }}</span></td><td class="text-end"><div class="btn-group btn-group-sm"><button class="btn btn-outline-primary" :disabled="updating === report.id" @click="updateStatus(report.id, 'In review')">Review</button><button class="btn btn-outline-primary" :disabled="updating === report.id" @click="updateStatus(report.id, 'Resolved')">Resolve</button><button class="btn btn-outline-secondary" :disabled="updating === report.id" @click="updateStatus(report.id, 'Dismissed')">Dismiss</button></div></td></tr></tbody></table></div></section></template></div></section>
</template>

<style scoped>
.stat-label { color: var(--um-muted); font-size: .86rem; font-weight: 700; }.stat-value { display: block; margin: .5rem 0; color: var(--um-green); font-size: 2.35rem; letter-spacing: -.05em; }.stat-note { color: var(--um-coral); font-size: .78rem; font-weight: 750; }.admin-heading { color: var(--um-ink); font-size: 1.45rem; font-weight: 800; }.table th { color: var(--um-muted); font-size: .75rem; text-transform: uppercase; }.table td { padding: 1rem .5rem; color: var(--um-ink); }.table small { display: block; color: var(--um-muted); margin-top: .2rem; }.status-pill { display: inline-block; border-radius: 99px; padding: .32rem .55rem; font-size: .72rem; font-weight: 800; }.open { color: #a85b11; background: #fff0d7; }.in-review { color: #205e87; background: #dceef9; }.resolved { color: var(--um-green); background: var(--um-green-light); }.dismissed { color: #6d706b; background: #ecece8; }
</style>
